def solve(x):
    defaults = x.get('defaults', {})
    environment = x.get('environment', {})
    explicit = x.get('explicit', {})

    result = {}

    for key in defaults:
        if key in environment:
            result[key] = environment[key]
        elif key in explicit:
            result[key] = explicit[key]
        else:
            result[key] = defaults[key]

    for key in environment:
        if key not in result:
            result[key] = environment[key]

    for key in explicit:
        if key not in result:
            result[key] = explicit[key]

    return result
